import{J as e,n as t,ot as n,q as r}from"./chunks/framework.BCRZU8Rs.js";var i=JSON.parse(`{"title":"Slice 4 decision: no shared work board yet","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Slice 4 decision: no shared work board yet"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/plans/worldgen-decoupling-slice4-decision"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/plans/worldgen-decoupling-slice4-decision"}]],"editSource":{"kind":"file","url":"https://github.com/JSPrismarine/JSPrismarine/edit/master/docs/plans/worldgen-decoupling-slice4-decision.md"}},"headers":[],"relativePath":"plans/worldgen-decoupling-slice4-decision.md","filePath":"plans/worldgen-decoupling-slice4-decision.md","lastUpdated":1794210744000}`),a={name:`plans/worldgen-decoupling-slice4-decision.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<div><h1 id="slice-4-decision-no-shared-work-board-yet" tabindex="-1">Slice 4 decision: no shared work board yet <a class="header-anchor" href="#slice-4-decision-no-shared-work-board-yet" aria-label="Permalink to “Slice 4 decision: no shared work board yet”">​</a></h1><p><a href="/pr-preview/pr-3045/plans/worldgen-decoupling.html">worldgen-decoupling.md</a> says slice 4 is worth doing only if slice 0&#39;s task durations show enough tasks longer than about 10 ms that an arriving <code>immediate</code> task waits noticeably, or if tick stalls leave workers idle. This note records the data and the decision. The figures are from <a href="/pr-preview/pr-3045/research/worldgen-decoupling-baseline.html">worldgen-decoupling-baseline.md</a>, taken at load averages of 3 to 6.</p><h2 id="the-data" tabindex="-1">The data <a class="header-anchor" href="#the-data" aria-label="Permalink to “The data”">​</a></h2><ul><li>Every <code>terrain</code> task is longer than 10 ms at one worker and at six, with means of 29 to 74 ms and a worst case of 430 ms.</li><li><code>features</code> tasks are short with one worker (mean 8.5 to 9.8 ms, 11 to 20% over 10 ms) and long with six (mean 30 to 37 ms, all over 10 ms). CPU time per task rises with the worker count, so some of the growth is contention, not longer work.</li><li>The tick&#39;s own work stayed small during a full-speed preload: mean 1.3 to 2.0 ms, 99th percentile 6 to 15 ms against a 50 ms period.</li><li>Lateness at the 99th percentile rose to 250 to 390 ms during the preload, with or without a host process, and the tick&#39;s work did not grow. Something holds the event loop between ticks. The runs do not say what, and the control run with no generation also reached 268 ms once.</li></ul><h2 id="why-that-does-not-justify-the-board" tabindex="-1">Why that does not justify the board <a class="header-anchor" href="#why-that-does-not-justify-the-board" aria-label="Permalink to “Why that does not justify the board”">​</a></h2><p>The board fixes one thing: workers that wait for the main thread to hand them the next task. The research note measured that cost as the main thread&#39;s stall divided by the task length, and showed it large only when the tick holds the thread for most of its 50 ms and tasks are 10 ms or less. Here tasks are mostly 30 ms or more, and the tick holds the thread for a few milliseconds. Nothing in the data shows workers idle behind the main thread. The throughput per worker count (chunks per CPU-second falling as workers are added) points at contention between workers, which a board does not change.</p><p>The <code>immediate</code> backlog waits in the task table (90 to 266 ms) come from <code>bench:chunks</code> asking for 64 chunks in one burst, not from a player arriving behind a long task, so they do not measure what slice 4 would fix.</p><h2 id="what-would-change-the-decision" tabindex="-1">What would change the decision <a class="header-anchor" href="#what-would-change-the-decision" aria-label="Permalink to “What would change the decision”">​</a></h2><ul><li>A bot fleet run, which I could not complete with a preload: ticks under real player load. If their 99th percentile nears 45 ms while workers sit idle with tasks queued, the board is justified.</li><li>An <code>immediate</code> arrival measured behind a running <code>terrain</code> task under that load, with a wait well above one task length.</li><li>Short tasks becoming the goal in themselves. Splitting <code>terrain</code> and <code>features</code> into 5 to 10 ms tasks is a separate decision from the board, and the order-independence digests already allow it. The data above shows the terrain tasks are the long ones.</li></ul><p>No prototype was built.</p></div>`,1)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};